/**
 * The TripleStore owns an {@link AdjacencyCommitLog} and appends one record for every data-revision bump, whatever
 * route the commit took and whether or not an adjacency collector is attached. After every commit the log head equals
 * the data revision, the log is contiguous, no record is staged, and no record is {@code EMPTY}.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
@Timeout(120)
class AdjacencyCommitLogMirrorsDataRevisionTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI G = VF.createIRI("urn:g");

	@TempDir
	File dataDir;

	private SailRepository repository;
	private LmdbStore sail;

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig adjacencyConfig() {
		return new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30)
				.setInitialRunImportEnabled(false);
	}

	private void open(LmdbStoreConfig config) {
		sail = new LmdbStore(dataDir, config);
		repository = new SailRepository(sail);
		repository.init();
		LmdbDirectAdjacencyStore adjacency = sail.getBackingStore().directAdjacencyStore();
		if (adjacency != null) {
			// this test is about the log: keep the applier from consuming (and trimming) the records it checks
			adjacency.pauseApplierForTest(true);
		}
	}

	private TripleStore tripleStore() {
		return sail.getBackingStore().getTripleStore();
	}

	private AdjacencyCommitLog log() {
		return tripleStore().adjacencyCommitLog();
	}

	private static IRI s(int i) {
		return VF.createIRI("urn:s" + i);
	}

	private static IRI o(int i) {
		return VF.createIRI("urn:o" + i);
	}

	@Test
	void everyIsolationLevelProducesExactlyOneRecordPerCommit() {
		open(adjacencyConfig());
		// the first NONE write into an empty store is the initial NONE import, covered separately below
		commitOne(IsolationLevels.READ_COMMITTED, 999);
		int next = 0;
		for (IsolationLevel level : new IsolationLevel[] { IsolationLevels.NONE, IsolationLevels.READ_COMMITTED,
				IsolationLevels.SNAPSHOT_READ, IsolationLevels.SNAPSHOT, IsolationLevels.SERIALIZABLE }) {
			long before = log().headRevision();
			try (SailRepositoryConnection conn = repository.getConnection()) {
				conn.begin(level);
				conn.add(s(next), P, o(next));
				conn.add(s(next + 1), P, o(next + 1));
				conn.commit();
			}
			next += 2;
			assertMirrored();
			assertThat(log().headRevision()).as("one revision per commit at %s", level).isEqualTo(before + 1);
			Record record = awaitSealed(log().record(before + 1));
			assertThat(record.kind()).as("a collected commit at %s", level).isEqualTo(Kind.DELTA);
			assertThat(record.pending()).isInstanceOf(PendingTable.class);
			assertThat(((PendingTable) record.pending()).revision()).isEqualTo(before + 1);
		}
	}

	@Test
	void aRollbackLeavesNeitherARecordNorAStagedEntry() {
		open(adjacencyConfig());
		commitOne(IsolationLevels.READ_COMMITTED, 0);
		long before = log().headRevision();
		for (IsolationLevel level : new IsolationLevel[] { IsolationLevels.READ_COMMITTED,
				IsolationLevels.SNAPSHOT }) {
			try (SailRepositoryConnection conn = repository.getConnection()) {
				conn.begin(level);
				conn.add(s(10), P, o(10));
				conn.rollback();
			}
			assertMirrored();
			assertThat(log().headRevision()).isEqualTo(before);
		}
	}

	@Test
	void clearingAContextRecordsOneDeltaRecord() {
		open(adjacencyConfig());
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(IsolationLevels.READ_COMMITTED);
			for (int i = 0; i < 20; i++) {
				conn.add(s(i), P, o(i), G);
			}
			conn.commit();
		}
		long before = log().headRevision();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(IsolationLevels.READ_COMMITTED);
			conn.clear(G);
			conn.commit();
		}
		assertMirrored();
		assertThat(log().headRevision()).isEqualTo(before + 1);
		assertThat(awaitSealed(log().record(before + 1)).kind()).isEqualTo(Kind.DELTA);
	}

	@Test
	void reAddingAnExistingStatementNeverProducesAnEmptyRecord() {
		open(adjacencyConfig());
		commitOne(IsolationLevels.READ_COMMITTED, 0);
		commitOne(IsolationLevels.READ_COMMITTED, 0);
		commitOne(IsolationLevels.NONE, 0);
		assertMirrored();
	}

	@Test
	void aNoneTransactionWithSeveralUpdatesAdvancesTheHeadPerUpdate() {
		open(adjacencyConfig());
		long before = log().headRevision();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(IsolationLevels.NONE);
			conn.prepareUpdate("INSERT DATA { <urn:s100> <urn:p> <urn:o100> }").execute();
			conn.prepareUpdate("INSERT DATA { <urn:s101> <urn:p> <urn:o101> }").execute();
			assertThat(log().headRevision())
					.as("each NONE update publishes its own revision")
					.isGreaterThanOrEqualTo(before + 2);
			assertThat(log().headRevision()).isEqualTo(tripleStore().getDataRevision());
			conn.commit();
		}
		assertMirrored();
	}

	@Test
	void mapGrowthRetriesKeepOneRecordPerCommit() {
		open(adjacencyConfig()
				.setTripleDBSize(256L * 1024)
				.setValueDBSize(256L * 1024)
				.setAutoGrow(true));
		long tripleMap = tripleStore().mapSizeBytes();
		long valueMap = sail.getBackingStore().valueStore().mapSizeBytes();
		long before = log().headRevision();
		String padding = "x".repeat(200);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(IsolationLevels.READ_COMMITTED);
			for (int i = 0; i < 4_000; i++) {
				Literal literal = VF.createLiteral(padding + i);
				conn.add(s(i), P, literal);
			}
			conn.commit();
		}
		assertThat(tripleStore().mapSizeBytes() > tripleMap
				|| sail.getBackingStore().valueStore().mapSizeBytes() > valueMap)
						.as("the commit must have grown a map and replayed")
						.isTrue();
		assertMirrored();
		assertThat(log().headRevision()).isEqualTo(before + 1);
		assertThat(awaitSealed(log().record(before + 1)).kind()).isEqualTo(Kind.DELTA);
	}

	@Test
	void withoutAnAdjacencyCollectorEveryRevisionIsAnOverflowedRecord() {
		open(new LmdbStoreConfig("spoc,posc").setInitialRunImportEnabled(false));
		for (int i = 0; i < 3; i++) {
			commitOne(IsolationLevels.READ_COMMITTED, i);
		}
		commitOne(IsolationLevels.NONE, 10);
		assertMirrored();
		assertThat(log().headRevision()).isGreaterThanOrEqualTo(4);
		for (long r = log().floorRevision() + 1; r <= log().headRevision(); r++) {
			assertThat(log().record(r).kind()).as("revision %d without a collector", r).isEqualTo(Kind.OVERFLOWED);
		}
	}

	@Test
	void anOverflowedDeltaIsRecordedAsAGap() {
		String previous = System.getProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY);
		System.setProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY, "1");
		try {
			open(adjacencyConfig());
			long before = log().headRevision();
			try (SailRepositoryConnection conn = repository.getConnection()) {
				conn.begin(IsolationLevels.READ_COMMITTED);
				for (int i = 0; i < 50; i++) {
					conn.add(s(i), P, o(i));
				}
				conn.commit();
			}
			assertMirrored();
			assertThat(log().headRevision()).isEqualTo(before + 1);
			assertThat(awaitSealed(log().record(before + 1)).kind()).isEqualTo(Kind.OVERFLOWED);
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY);
			} else {
				System.setProperty(LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY, previous);
			}
		}
	}

	/**
	 * The first NONE write into an empty store with adjacency enabled is the initial NONE import: the sail store
	 * detaches the collector for its duration, so its revisions are recorded as gaps, and the log stays contiguous
	 * through it.
	 */
	@Test
	void theInitialNoneImportKeepsTheLogContiguous() {
		open(adjacencyConfig().setInitialRunImportEnabled(true));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(IsolationLevels.NONE);
			for (int i = 0; i < 200; i++) {
				conn.add(s(i), P, o(i));
			}
			conn.commit();
		}
		assertMirrored();
		long afterImport = log().headRevision();
		assertThat(afterImport).isGreaterThanOrEqualTo(1);
		for (long r = log().floorRevision() + 1; r <= afterImport; r++) {
			assertThat(log().record(r).kind()).as("import revision %d has no collector", r).isEqualTo(Kind.OVERFLOWED);
		}
		commitOne(IsolationLevels.READ_COMMITTED, 500);
		assertMirrored();
		assertThat(log().headRevision()).isEqualTo(afterImport + 1);
		assertThat(awaitSealed(log().record(afterImport + 1)).kind()).isEqualTo(Kind.DELTA);
	}

	private void commitOne(IsolationLevel level, int i) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin(level);
			conn.add(s(i), P, o(i));
			conn.commit();
		}
	}

	/** The log mirrors the data revision exactly: same head, contiguous, nothing staged, no EMPTY record. */
	private void assertMirrored() {
		AdjacencyCommitLog log = log();
		assertThat(log.headRevision()).as("log head equals the data revision")
				.isEqualTo(tripleStore().getDataRevision());
		assertThat(log.hasStaged()).as("no record stays staged after a commit completes").isFalse();
		assertThat(log.record(log.floorRevision())).isNull();
		for (long r = log.floorRevision() + 1; r <= log.headRevision(); r++) {
			Record record = log.record(r);
			assertThat(record).as("record at revision %d", r).isNotNull();
			assertThat(record.revision()).isEqualTo(r);
			awaitSealed(record);
			assertThat(record.kind())
					.as("a triple mutation always records at least one event; revision %d", r)
					.isNotEqualTo(Kind.EMPTY);
			if (record.kind() == Kind.DELTA) {
				assertThat(record.pending()).as("a sealed delta carries its pending table").isNotNull();
			}
		}
	}

	private static Record awaitSealed(Record record) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (!record.sealed()) {
			if (System.nanoTime() > deadline) {
				throw new AssertionError("record never sealed: " + record);
			}
			Thread.onSpinWait();
		}
		return record;
	}
}
